
# Import pandas to read and summarize the experiment results.
import pandas as pd

# Import Path to locate saved CSV files.
from pathlib import Path


# Locate the folder containing evaluation results.
RESULT_DIR = Path("results/metrics")

# Find all CSV files generated by the multi-seed experiments.
files = sorted(
    RESULT_DIR.glob("drift_replay_comparison_seed_*.csv")
)

# Store the summary of each experiment.
rows = []

# Process each experiment's results.
for file in files:

    # Extract the random seed from the filename.
    seed = file.stem.split("_")[-1]

    # Read the evaluation results.
    data = pd.read_csv(file)

    # Select only the overall performance results.
    overall = data[data["phase"] == "Overall"]

    # Extract the F1-score for each strategy.
    baseline = overall[
        overall["strategy"] == "Baseline online learning"
    ]["f1"].iloc[0]

    replay = overall[
        overall["strategy"] == "ADWIN-triggered replay"
    ]["f1"].iloc[0]

    # Record the scores and their difference.
    rows.append({
        "seed": seed,
        "baseline_f1": baseline,
        "replay_f1": replay,
        "f1_difference": replay - baseline
    })


# Check whether any experiment files were found.
if not rows:
    print("No multi-seed results found.")
    print("Run the five evaluation experiments first.")

else:
    # Convert the results into a summary table.
    summary = pd.DataFrame(rows)

    # Display each experiment's F1-scores.
    print("\nMULTI-SEED F1 COMPARISON")
    print(summary.round(4).to_string(index=False))

    # Calculate average performance.
    print("\nAVERAGE PERFORMANCE")
    print("Average baseline F1:", round(summary["baseline_f1"].mean(), 4))
    print("Average replay F1:", round(summary["replay_f1"].mean(), 4))
    print("Average F1 difference:", round(summary["f1_difference"].mean(), 4))

    # Count how often replay improved performance.
    improvements = (summary["f1_difference"] > 0).sum()

    print("Replay improved in:", improvements, "out of", len(summary), "runs")


# Compare average performance across all five random seeds.
# This reads existing CSV files and does not retrain models.

metrics = [
    "accuracy",
    "precision",
    "recall",
    "f1",
    "false_positive_rate"
]

# Collect the overall metrics from every experiment.
all_results = []

for file in files:
    # Read the results for one random seed.
    data = pd.read_csv(file)

    # Keep the overall results only.
    overall = data[data["phase"] == "Overall"].copy()

    # Record the seed associated with these results.
    overall["seed"] = file.stem.split("_")[-1]

    all_results.append(overall)

if all_results:
    # Combine results from all five experiments.
    combined = pd.concat(all_results, ignore_index=True)

    # Calculate the average metric for each learning strategy.
    averages = combined.groupby("strategy")[metrics].mean()

    # Display the comparison.
    print("\nAVERAGE CLASSIFICATION METRICS")
    print(averages.round(4).to_string())

    # Save the results for later reporting.
    output_file = RESULT_DIR / "drift_replay_average_metrics.csv"
    averages.to_csv(output_file)

    print("\nAverage metrics saved to:", output_file)
